#!/usr/bin/env node
// Generate lib/assets.generated.mjs: the skill and AGENTS.md snippet texts plus
// the package version, as string constants. `setup`, `doctor`, and `uninstall`
// use these instead of reading files next to the code, so a `bun build
// --compile` binary needs no source tree. Run by `npm test` (pretest) and
// `npm run build:bin`; `--check` exits 1 when the generated file is stale.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const CLIENT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT = path.join(CLIENT, "lib", "assets.generated.mjs");

// key -> [source file relative to client/, install path relative to the project]
export const ASSETS = {
  claudeRemember: ["claude/skills/remember/SKILL.md", ".claude/skills/remember/SKILL.md"],
  claudeInit: ["claude/skills/memmem-init/SKILL.md", ".claude/skills/memmem-init/SKILL.md"],
  agentsInit: ["agents/skills/memmem-init/SKILL.md", ".agents/skills/memmem-init/SKILL.md"],
};
const SNIPPET = "codex/AGENTS.snippet.md";

export function render() {
  const read = (rel) => fs.readFileSync(path.join(CLIENT, rel), "utf8");
  const version = JSON.parse(read("package.json")).version;
  const skills = Object.entries(ASSETS).map(([key, [src, dest]]) =>
    `  ${key}: { source: ${JSON.stringify(src)}, dest: ${JSON.stringify(dest)}, text: ${JSON.stringify(read(src))} },`);
  return [
    "// GENERATED by scripts/embed-assets.mjs from the files named below. Do not edit;",
    "// edit the source files and run `node scripts/embed-assets.mjs`.",
    `export const VERSION = ${JSON.stringify(version)};`,
    "export const SKILLS = {",
    ...skills,
    "};",
    `export const AGENTS_SNIPPET = ${JSON.stringify(read(SNIPPET))};`,
    "",
  ].join("\n");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const next = render();
  const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : null;
  if (process.argv.includes("--check")) {
    if (cur !== next) { process.stderr.write(`${OUT} is stale; run node scripts/embed-assets.mjs\n`); process.exit(1); }
  } else if (cur !== next) {
    fs.writeFileSync(OUT, next);
    process.stdout.write(`wrote ${path.relative(CLIENT, OUT)}\n`);
  }
}
